            def rebuild(a,speed,duration):return np.column_stack([a[:,31] if keep[31] else np.zeros(len(a)),a[:,15] if keep[15] else np.zeros(len(a)),np.log1p(np.sqrt(np.mean((a[:,keep]-a[:,keep].mean(1,keepdims=True))**2,axis=1))),np.log(speed),duration])
